<script>
import Layout from "../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";
import { Modal } from "bootstrap";
export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
  },
  data() {
    return {
      users: [],
      Users: {},
      roles: [],
      page: 1,
      limit: 20,
      tot_pages: 0,
      searchUsers: null,
      SearchMode: false,
      emps: [],
      new_roles: [],
      newRoles: [{}],
      addRoles: [{}],
      editRoles: [{}],
      branches: [],
      user_info: {},
      new_pass: "",
      users_switch: "",
      user_status: 0,
      data: { pass: "" },
      selectedUser: { user_roles: [] },
      cashAccounts: [],
      add_modal: {},
      edit_modal: {},
      edit_pass_modal: {},
      formTried: false,
      editFormTried: false,
    };
  },

  methods: {
    editUser() {
      let cash_account_id = null;
      if (this.checkEditRoles) {
        cash_account_id = this.selectedUser?.cash_account_id;
      }
      this.http
        .put("users", this.selectedUser.id, {
          roles: this.editRoles,
          name: this.selectedUser?.name,
          email: this.selectedUser?.email,
          cash_account_id,
        })
        .then((res) => {
          if (res.status) {
            this.get(this.page);
            this.edit_modal.hide();
          }
        });
    },
    addUsers() {
      this.data.new_roles = this.addRoles;
      this.http.post("users/register", this.data).then((res) => {
        if (res.status) {
          this.get(this.page);
          this.add_modal.hide();
        }
      });
    },
    search() {
      this.SearchMode = true;
      console.log(this.searchUsers);
      this.tot_pages = 0;
      this.http
        .post("users/search", {
          limit: this.limit,
          page: this.page,
          search: this.searchUsers,
          col: "name",
        })
        .then((res) => {
          this.users = res.data;
        });
    },
    cancelSearchMode() {
      this.searchUsers = "";
      this.SearchMode = false;
      this.get(this.page);
    },
    getUsers() {
      this.http.get("users").then((res) => {
        this.users = res.data;
      });
    },
    selectUser(user) {
      this.selectedUser = { ...user };
      console.log("this s user", this.selectedUser);

      this.editRoles = this.selectedUser?.user_roles.map((user_role) => {
        return {
          id: user_role?.id,
          role_id: user_role?.role?.id,
          name: user_role?.role?.role,
          name_en: user_role?.role?.role_en,
        };
      });
    },
    deleteUser(user) {
      var data = {
        title: "popups.deleteuser",
        msg: "popups.deletemsg",
      };
      this.popup.confirm(data).then((res) => {
        if (res) {
          console.log(user);
          this.http.delete("users", user.id).then(() => {
            this.get(this.page);
          });
        }
      });
    },
    userInfo(user) {
      this.user_info = user;
      console.log(this.user_info);
    },
    editPass() {
      console.log(this.user_info.id);
      this.http
        .post("users/update-password", {
          emp_id: this.user_info.id,
          pass: this.new_pass,
        })
        .then((res) => {
          if (res.status) {
            this.new_pass = "";
            this.edit_pass_modal.hide();
          }
        });
    },
    getCashAccounts() {
      this.http.get("cash-accounts/cash").then((res) => {
        this.cashAccounts = res.data;
      });
    },
    get(page) {
      // console.log(this.userstable);
      this.http
        .post("users/pagination", {
          limit: this.limit,
          page: page,
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.users = res.data;
        });
    },
    getEmps() {
      this.http.get("emps/users").then((res) => {
        this.emps = res.data;
      });
    },
    getRoles() {
      this.http.get("roles").then((res) => {
        this.roles = res.data;
      });
    },
    getSwitch(user, status) {
      console.log(status);
      this.http
        .post("users/update-status", {
          status: status,
          current_user_id: user.id,
        })
        .then((res) => {
          if (res.status) this.get(this.page);
        });
    },
    deleteRoleOption(index, type) {
      if (type == "add") return this.addRoles.splice(index, 1);
      this.editRoles.splice(index, 1);
    },
    handleSubmit() {
      this.formTried = true;
      if (!this.isPasswordValid) return;
      this.addUsers();
    },
    handleEditPass() {
      this.editFormTried = true;
      if (!this.isEditPasswordValid) return;
      this.editPass();
    },
  },
  computed: {
    checkAddRoles() {
      let isEdit = false;
      this.addRoles.forEach((item) => {
        this.roles.forEach((role) => {
          if (item?.role_id == role?.id && role?.code == "cashier") {
            isEdit = true;
          }
        });
      });
      return isEdit;
    },
    checkEditRoles() {
      let isEdit = false;
      this.editRoles.forEach((item) => {
        this.roles.forEach((role) => {
          if (item?.role_id == role?.id && role?.code == "cashier") {
            isEdit = true;
          }
        });
      });
      return isEdit;
    },

    passwordStrength() {
      const pass = this.data.pass;
      let score = 0;
      if (pass.length >= 8) score++;
      if (/[A-Z]/.test(pass)) score++;
      if (/[a-z]/.test(pass)) score++;
      if (/\d/.test(pass)) score++;
      if (/[@$!%*?&]/.test(pass)) score++;
      if (score <= 2) return "weak";
      if (score === 3 || score === 4) return "medium";
      return "strong";
    },
    editPasswordStrength() {
      const pass = this.new_pass;
      let score = 0;
      if (pass.length >= 8) score++;
      if (/[A-Z]/.test(pass)) score++;
      if (/[a-z]/.test(pass)) score++;
      if (/\d/.test(pass)) score++;
      if (/[@$!%*?&]/.test(pass)) score++;
      if (score <= 2) return "weak";
      if (score === 3 || score === 4) return "medium";
      return "strong";
    },
    isPasswordValid() {
      const pass = this.data.pass;
      return (
        pass.length >= 8 &&
        /[A-Z]/.test(pass) &&
        /[a-z]/.test(pass) &&
        /\d/.test(pass) &&
        /[@$!%*?&]/.test(pass)
      );
    },
    isEditPasswordValid() {
      const pass = this.new_pass;
      return (
        pass.length >= 8 &&
        /[A-Z]/.test(pass) &&
        /[a-z]/.test(pass) &&
        /\d/.test(pass) &&
        /[@$!%*?&]/.test(pass)
      );
    },
  },
  created() {
    // this.get(1);
    this.getRoles();
    this.getEmps();
    this.getCashAccounts();
  },
  mounted() {
    this.add_modal = new Modal("#addModal");
    this.edit_modal = new Modal("#editModal");
    this.edit_pass_modal = new Modal("#editPassModal");
    this.get(1);
  },
};
</script>

<template>
  <Layout>
    <PageHeader
      :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'"
      :title="$t('menu.menuitems.users.text')"
    />
    <div class="card">
      <div class="card-body">
        <div class="row">
          <div class="col-6">
            <div class="search-box chat-search-box" style="width: 250px">
              <div class="position-relative">
                <input
                  @keyup="search()"
                  type="text"
                  class="form-control fa-lg text-light"
                  :dir="$i18n.locale == 'ar' ? 'rtl' : ''"
                  :placeholder="$t('users.searchplaceholder')"
                  v-model="searchUsers"
                  style="background-color: #2a3042 !important"
                />
                <i class="bx bx-search-alt search-icon text-light"></i>
                <button
                  @click="cancelSearchMode()"
                  v-if="SearchMode"
