                  style="position: absolute; top: 12px; left: 250px"
                ></button>
              </div>
            </div>
          </div>
          <div class="col-6" style="display: flex; justify-content: flex-end">
            <button
              type="button"
              class="btn btn-light float-end mb-4"
              @click="add_modal.show()"
            >
              <span
                class="bx bxs-plus-circle float-end fa-2x"
                style="color: #2a3042 !important"
              ></span>
            </button>
          </div>
        </div>

        <div class="table-responsive">
          <table
            :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'"
            class="table table-centered table-nowrap table-striped table-hover align-middle"
          >
            <thead>
              <tr
                class="text-light"
                style="background-color: #2a3042 !important"
              >
                <th scope="col">#</th>
                <th scope="col">{{ $t("users.userstable.user") }}</th>
                <th scope="col">{{ $t("users.userstable.email") }}</th>
                <th scope="col">{{ $t("users.userstable.branch") }}</th>
                <th scope="col">{{ $t("users.userstable.roles") }}</th>
                <th scope="col">{{ $t("users.userstable.created") }}</th>
                <th scope="col">{{ $t("users.userstable.updated") }}</th>
                <th scope="col">
                  {{ $t("users.userstable.operations") }}
                </th>
              </tr>
            </thead>
            <tbody>
              <tr class="" v-for="(user, index) in users" :key="user.id">
                <td>{{ index + 1 }}</td>
                <td>{{ user.name }}</td>
                <td>{{ user.email }}</td>
                <td>
                  {{
                    $i18n.locale == "ar"
                      ? user?.emp?.branch?.name
                      : user?.emp?.branch?.name_en
                  }}
                </td>
                <td>
                  <button
                    class="btn btn-primary me-2 btn-sm"
                    data-bs-toggle="modal"
                    data-bs-target="#showRolesModal"
                    @click="selectUser(user)"
                  >
                    <span class="bx bx-show-alt fa-lg text-light"></span>
                  </button>
                </td>
                <!-- <td>{{ user.created.split("T")[0] }}</td>
                <td>{{ user.updated.split("T")[0] }}</td> -->
                <td>
                  <button
                    type="button"
                    @click="getSwitch(user, 0)"
                    v-if="user.status == 1"
                    class="btn btn-secondary btn-sm"
                    style="margin-inline-end: 4px"
                  >
                    {{ $t("popups.disable") }}
                  </button>
                  <button
                    @click="getSwitch(user, 1)"
                    v-else
                    class="btn btn-primary btn-sm"
                    style="margin-inline-end: 4px"
                  >
                    {{ $t("popups.enable") }}
                  </button>

                  <button
                    type="button"
                    class="btn btn-primary btn-sm"
                    style="margin-inline-end: 4px"
                    @click="
                      selectUser(user);
                      edit_modal.show();
                    "
                  >
                    {{ $t("popups.edit") }}
                  </button>
                  <button
                    type="button"
                    class="btn btn-primary btn-sm"
                    style="margin-inline-end: 4px"
                    @click="
                      userInfo(user);
                      edit_pass_modal.show();
                    "
                  >
                    {{ $t("popups.resetpass") }}
                  </button>
                  <a
                    class="btn btn-danger btn-sm"
                    style="margin-inline-end: 4px"
                    :class="{}"
                    href="javascript:void(0)"
                    role="button"
                    @click="deleteUser(user)"
                    >{{ $t("popups.delete") }}</a
                  >
                </td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </div>
    <!-- end  table -->

    <!-- start show roles modal -->
    <div
      class="modal fade"
      id="showRolesModal"
      tabindex="-1"
      aria-labelledby="exampleModalLabel"
      aria-hidden="true"
      :dir="$i18n.locale == 'ar' ? 'rtl' : ''"
    >
      <div class="modal-dialog">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title" id="exampleModalLabel">
              {{ $t("users.roles") }}
            </h5>
            <button
              type="button"
              class="btn-close"
              style="margin: 0"
              data-bs-dismiss="modal"
              aria-label="Close"
            ></button>
          </div>

          <div class="modal-body p-4">
            <div class="table-responsive">
              <table
                :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'"
                class="table table-centered table-nowrap table-striped table-hover align-middle"
              >
                <thead>
                  <tr
                    class="text-light"
                    style="background-color: #2a3042 !important"
                  >
                    <th scoped="col">#</th>
                    <th scoped="col">{{ $t("users.role") }}</th>
                  </tr>
                </thead>
                <tbody>
                  <tr
                    v-for="(userRole, index) in selectedUser?.user_roles"
                    :key="userRole"
                  >
                    <td>{{ index + 1 }}</td>
                    <td>
                      {{
                        $i18n.locale == "ar"
                          ? userRole?.role?.role
                          : userRole?.role?.role_en
                      }}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
    <!-- end show roles modal -->
    <!--Start Add Modal-->
    <div
      class="modal fade"
      id="addModal"
      tabindex="-1"
      aria-labelledby="exampleModalLabel"
      aria-hidden="true"
      :dir="$i18n.locale == 'ar' ? 'rtl' : ''"
    >
      <div class="modal-dialog">
        <div class="modal-content">
          <form @submit.prevent="handleSubmit()">
            <div class="modal-header">
              <h5 class="modal-title" id="exampleModalLabel">
                {{ $t("popups.adduser") }}
              </h5>
              <button
                type="button"
                class="btn-close"
                data-bs-dismiss="modal"
                aria-label="Close"
                style="margin: 0"
              ></button>
            </div>

            <div class="modal-body">
              <div class="mb-3">
                <label for="user">{{ $t("popups.employee") }}</label>
                <select v-model="data.emp_id" class="form-select">
                  <option v-for="emp in emps" :key="emp" :value="emp.id">
                    {{ emp.name }}
                  </option>
                </select>
              </div>

              <div class="mb-3">
                <label for="usename">{{ $t("popups.username") }}</label>
                <input
                  v-model="data.name"
                  id="user"
                  required
                  class="form-control"
                  type="text"
                  :placeholder="$t('popups.username')"
                />
              </div>

              <div class="mb-3">
                <label for="user">{{ $t("popups.email") }}</label>
                <input
                  v-model="data.email"
                  id="user"
                  required
                  class="form-control"
                  type="text"
                  :placeholder="$t('popups.email')"
                />
              </div>

              <div
                class="p-4 border border-primary-subtle rounded-3 bg-body-tertiary shadow-sm mt-4 mb-4"
              >
                <label for="pass" class="form-label">{{
                  $t("popups.password")
                }}</label>
                <input
                  v-model="data.pass"
                  id="pass"
                  type="password"
                  class="form-control"
                  :placeholder="$t('popups.password')"
                  required
                />

                <!-- Password Rules -->
                <ul class="mt-2 list-unstyled small">
                  <li
                    :class="{
                      'text-success': data.pass.length >= 8,
                      'text-muted': data.pass.length < 8,
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        data.pass.length >= 8
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.length") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /[A-Z]/.test(data.pass),
                      'text-muted': !/[A-Z]/.test(data.pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /[A-Z]/.test(data.pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.uppercase") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /[a-z]/.test(data.pass),
                      'text-muted': !/[a-z]/.test(data.pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /[a-z]/.test(data.pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.lowercase") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /\d/.test(data.pass),
                      'text-muted': !/\d/.test(data.pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /\d/.test(data.pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.number") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /[@$!%*?&]/.test(data.pass),
                      'text-muted': !/[@$!%*?&]/.test(data.pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /[@$!%*?&]/.test(data.pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.special") + " (@$!%*?&)" }}
                  </li>
                </ul>

                <!-- Password Strength -->
                <div class="mt-1">
                  <span
                    class="fw-bold"
                    :class="{
                      'text-danger': passwordStrength === 'weak',
                      'text-warning': passwordStrength === 'medium',
                      'text-success': passwordStrength === 'strong',
                    }"
                  >
                    {{ $t("popups.passwordStrength") }}:
                    {{ $t("popups.strength." + passwordStrength) }}
                  </span>
                </div>

                <!-- Validation error message -->
                <div
                  v-if="!isPasswordValid && formTried"
                  class="text-danger small mt-2"
                >
                  {{ $t("popups.passwordInvalid") }}
                </div>
              </div>
              <div class="mb-3">
                <div class="row d-flex align-items-center">
                  <div class="col">
                    <label for="user_role">{{ $t("popups.role") }}</label>
                  </div>
                  <div class="col d-flex justify-content-end">
                    <button
                      type="button"
                      @click="addRoles.push({})"
                      class="btn float-end"
                    >
                      <span
                        class="bx bxs-plus-circle float-end fa-2x"
                        style="color: #2a3042 !important"
                      ></span>
                    </button>
                  </div>
                </div>
                <div v-for="(role, index) in addRoles" :key="role">
                  <div class="row mt-2">
                    <div class="col">
                      <select
                        v-model="role.role_id"
                        style="display: inline"
                        class="form-select"
                        id="add_user_role"
                      >
                        <option v-for="r in roles" :key="r" :value="r.id">
                          {{ $i18n.locale == "ar" ? r.role : r.role_en }}
                        </option>
                      </select>
                    </div>
                    <div class="col-2">
                      <button
                        type="button"
                        class="btn btn-danger"
                        :disabled="addRoles.length <= 1"
                        @click="deleteRoleOption(index, 'add')"
                      >
                        <i class="bx bx-trash"></i>
                      </button>
                    </div>
                  </div>
                </div>
              </div>
              <div class="mb-3" v-if="checkAddRoles">
                <label for="exampleInputEmail1" class="form-label">
                  {{ $t("users.cash_account") }}
                </label>
                <select
                  required
                  class="form-select"
                  aria-label="Default select example"
                  v-model="data.cash_account_id"
                >
                  <option v-for="i in cashAccounts" :key="i" :value="i.id">
                    {{
                      $i18n.locale == "ar"
                        ? i.code + "-" + i?.name
                        : i.code + "-" + i?.name_en
                    }}
                  </option>
                </select>
              </div>
            </div>
            <div
              class="modal-footer"
              :dir="$i18n.locale == 'ar' ? 'rtl' : 'ltr'"
            >
              <button type="submit" class="btn btn-primary">
                {{ $t("popups.add") }}
              </button>
              <button
                data-bs-dismiss="modal"
                type="button"
                class="btn btn-danger"
              >
                {{ $t("popups.cancel") }}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
    <!--End Add Modal-->

    <!-- Edit Modal -->
    <div
      class="modal fade"
      id="editModal"
      tabindex="-1"
      aria-labelledby="exampleModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog">
        <div class="modal-content">
          <form @submit.prevent="editUser()">
            <div class="modal-header" :dir="$i18n.locale == 'ar' ? 'rtl' : ''">
              <h5 class="modal-title" id="exampleModalLabel">
                {{ $t("popups.edituser") }}
              </h5>
              <button
                type="button"
                class="btn-close"
                data-bs-dismiss="modal"
                aria-label="Close"
                style="margin: 0"
              ></button>
            </div>

            <div class="modal-body" :dir="$i18n.locale == 'ar' ? 'rtl' : ''">
              <div class="mb-3">
                <label for="user">{{ $t("popups.username") }}</label>
                <input
                  id="user"
                  required
                  class="form-control"
                  type="text"
                  :placeholder="$t('popups.username')"
                  v-model="selectedUser.name"
                />
              </div>

              <div class="mb-3">
                <label for="user">{{ $t("popups.email") }}</label>
                <input
                  v-model="selectedUser.email"
                  id="user"
                  required
                  class="form-control"
                  type="text"
                  :placeholder="$t('popups.email')"
                />
              </div>

              <div class="mb-3">
                <div class="row d-flex align-items-center">
                  <div class="col">
                    <label for="user_role">{{ $t("popups.role") }}</label>
                  </div>
                  <div class="col d-flex justify-content-end">
                    <button
                      type="button"
                      @click="editRoles.push({})"
                      class="btn float-end"
                    >
                      <span
                        class="bx bxs-plus-circle float-end fa-2x"
                        style="color: #2a3042 !important"
                      ></span>
                    </button>
                  </div>
                </div>
                <div v-for="(user_role, index) in editRoles" :key="user_role">
                  <div class="row mt-2">
                    <div class="col">
                      <select
                        v-model="user_role.role_id"
                        style="display: inline"
                        class="form-select"
                        id="edit_user_role"
                      >
                        <option
                          v-for="role in roles"
                          :key="role"
                          :value="role.id"
                          :selected="user_role.role_id == role?.id"
                        >
                          {{ $i18n.locale == "ar" ? role.role : role.role_en }}
                        </option>
                      </select>
                    </div>
                    <div class="col-2">
                      <button
                        type="button"
                        class="btn btn-danger"
                        :disabled="editRoles.length <= 1"
                        @click="deleteRoleOption(index, 'edit')"
                      >
                        <i class="bx bx-trash"></i>
                      </button>
                    </div>
                  </div>
                </div>
              </div>

              <div class="mb-3" v-if="checkEditRoles">
                <label for="exampleInputEmail1" class="form-label">
                  {{ $t("users.cash_account") }}
                </label>
                <select
                  class="form-select"
                  aria-label="Default select example"
                  v-model="selectedUser.cash_account_id"
                >
                  <option v-for="i in cashAccounts" :key="i" :value="i.id">
                    {{
                      $i18n.locale == "ar"
                        ? i.code + "-" + i?.name
                        : i.code + "-" + i?.name_en
                    }}
                  </option>
                </select>
              </div>
            </div>
            <div class="modal-footer" :dir="$i18n.locale == 'ar' ? 'rtl' : ''">
              <button type="submit" class="btn btn-primary">
                {{ $t("popups.edit") }}
              </button>
              <button
                data-bs-dismiss="modal"
                type="button"
                class="btn btn-danger"
              >
                {{ $t("popups.cancel") }}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
    <!--end Edit Modal-->
    <!--Edit Pass Modsl-->

    <div
      class="modal fade"
      id="editPassModal"
      tabindex="-1"
      aria-labelledby="exampleModalLabel"
      aria-hidden="true"
      :dir="$i18n.locale == 'ar' ? 'rtl' : ''"
    >
      <div class="modal-dialog">
        <div class="modal-content">
          <form @submit.prevent="handleEditPass()">
            <div class="modal-header">
              <h5 class="modal-title" id="exampleModalLabel">
                {{ $t("popups.resetpass") }}
              </h5>
              <button
                type="button"
                class="btn-close"
                data-bs-dismiss="modal"
                aria-label="Close"
                style="margin: 0"
              ></button>
            </div>

            <div class="modal-body">
              <div
                class="p-4 border border-primary-subtle rounded-3 bg-body-tertiary shadow-sm mt-4 mb-4"
              >
                <input
                  v-model="new_pass"
                  id="pass"
                  type="password"
                  class="form-control"
                  :placeholder="$t('popups.password')"
                  required
                />

                <!-- Password Rules -->
                <ul class="mt-2 list-unstyled small">
                  <li
                    :class="{
                      'text-success': new_pass.length >= 8,
                      'text-muted': new_pass.length < 8,
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        new_pass.length >= 8
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.length") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /[A-Z]/.test(new_pass),
                      'text-muted': !/[A-Z]/.test(new_pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /[A-Z]/.test(new_pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.uppercase") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /[a-z]/.test(new_pass),
                      'text-muted': !/[a-z]/.test(new_pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /[a-z]/.test(new_pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.lowercase") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /\d/.test(new_pass),
                      'text-muted': !/\d/.test(new_pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /\d/.test(new_pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.number") }}
                  </li>
                  <li
                    :class="{
                      'text-success': /[@$!%*?&]/.test(new_pass),
                      'text-muted': !/[@$!%*?&]/.test(new_pass),
                    }"
                  >
                    <i
                      class="bi"
                      :class="
                        /[@$!%*?&]/.test(new_pass)
                          ? 'bi-check-circle-fill'
                          : 'bi-circle'
                      "
                    ></i>
                    {{ $t("popups.passRules.special") + " (@$!%*?&)" }}
                  </li>
                </ul>

                <!-- Password Strength -->
                <div class="mt-1">
                  <span
                    class="fw-bold"
                    :class="{
                      'text-danger': editPasswordStrength === 'weak',
                      'text-warning': editPasswordStrength === 'medium',
                      'text-success': editPasswordStrength === 'strong',
                    }"
                  >
                    {{ $t("popups.passwordStrength") }}:
                    {{ $t("popups.strength." + editPasswordStrength) }}
                  </span>
                </div>

                <!-- Validation error message -->
                <div
                  v-if="!isEditPasswordValid && editFormTried"
                  class="text-danger small mt-2"
                >
                  {{ $t("popups.passwordInvalid") }}
                </div>
              </div>
            </div>
            <div class="modal-footer">
              <button type="submit" class="btn btn-primary">
                {{ $t("popups.edit") }}
              </button>
              <button
                data-bs-dismiss="modal"
                type="button"
                class="btn btn-danger"
              >
                {{ $t("popups.cancel") }}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
    <!--Edit pass Modal-->
    <!--   Apps  Pagination     -->
    <ul class="pagination pagination-rounded justify-content-center mb-2">
      <li class="page-item" :class="{ disabled: page == 1 }">
        <a
          class="page-link"
          href="javascript: void(0);"
          @click="get(page - 1)"
          aria-label="Previous"
        >
          <i class="mdi mdi-chevron-left"></i>
        </a>
      </li>
      <li
        class="page-item"
        :class="{ active: p == page }"
        v-for="p in tot_pages"
        :key="p"
      >
        <a class="page-link" href="javascript: void(0);" @click="get(p)">{{
          p
        }}</a>
      </li>

      <li class="page-item" :class="{ disabled: page == tot_pages }">
        <a
          class="page-link"
          href="javascript: void(0);"
          @click="get(page + 1)"
          aria-label="Next"
        >
          <i class="mdi mdi-chevron-right"></i>
        </a>
      </li>
    </ul>
    <!--end-->
  </Layout>
</template>
